import { NextResponse } from 'next/server';
import { TransactionFactory } from '@/lib/factories/transaction.factory';
import { PrismaClient } from "@prisma/client";
import { createClient } from "@/lib/supabase/client";

const prisma = new PrismaClient();
const transactionFactory = new TransactionFactory(prisma);
const supabase = createClient();

async function getUserIdFromToken(authHeader: string | null): Promise<string | null> {
  if (!authHeader?.startsWith('Bearer ')) {
    return null;
  }

  const token = authHeader.split(' ')[1];
  const { data: { user } } = await supabase.auth.getUser(token);
  return user?.id || null;
}

export async function POST(request: Request) {
  try {
    const authHeader = request.headers.get('authorization');
    const userId = await getUserIdFromToken(authHeader);

    if (!userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }
    
    const body = await request.json();
    const transactionData = await transactionFactory.createTransaction({
      ...body,
      userId
    });

    console.log(transactionData);
    

    const transaction = await prisma.transaction.create({
      data: {
        name: transactionData.name,
        type: transactionData.type,
        amountCAD: transactionData.amount_cad,
        amountUSD: transactionData.amount_usd || null,
        date: transactionData.date,
        notes: transactionData.notes || null,
        userId: transactionData.userId,
        monthId: transactionData.monthId,
        categoryId: 11 // Update with actual category logic
      }
    });

    return NextResponse.json(transaction);
  } catch (error) {
    console.error('Transaction creation error:', error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Failed to create transaction' },
      { status: 400 }
    );
  }
}

export async function GET(request: Request) {
  try {
    const authHeader = request.headers.get('authorization');
    const userId = await getUserIdFromToken(authHeader);

    if (!userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const transactions = await prisma.transaction.findMany({
      where: { userId }
    });
    
    return NextResponse.json(transactions);
  } catch (error) {
    return NextResponse.json({ error: 'Server error' }, { status: 500 });
  }
} 